452	static bool indexOfCanUseBloomFilter(const ASTPtr & parent)
453	{
454	    if (!parent)
455	        return true;
456	
457	    /// `parent` is a function where `indexOf` is located.
458	    /// Example: `indexOf(arr, x) = 1`, parent is a function named `equals`.
459	    if (const auto * function = parent->as<ASTFunction>())
460	    {
461	        if (function->name == "and")
462	        {
463	            return true;
464	        }
465	        else if (function->name == "equals" /// notEquals is not applicable
466	            || function->name == "greater" || function->name == "greaterOrEquals"
467	            || function->name == "less" || function->name == "lessOrEquals")
468	        {
469	            if (function->arguments->children.size() != 2)
470	                return false;
471	
472	            /// We don't allow constant expressions like `indexOf(arr, x) = 1 + 0` but it's negligible.
473	
474	            /// We should return true when the corresponding expression implies that the array contains the element.
475	            /// Example: when `indexOf(arr, x)` > 10 is written, it means that arr definitely should contain the element
476	            /// (at least at 11th position but it does not matter).
477	
478	            bool reversed = false;
479	            const ASTLiteral * constant = nullptr;
480	
481	            if (const ASTLiteral * left = function->arguments->children[0]->as<ASTLiteral>())
482	            {
483	                constant = left;
484	                reversed = true;
485	            }
486	            else if (const ASTLiteral * right = function->arguments->children[1]->as<ASTLiteral>())
487	            {
488	                constant = right;
489	            }
490	            else
491	                return false;
492	
493	            Field zero(0);
494	            return (function->name == "equals"  /// indexOf(...) = c, c != 0
495	                    && !applyVisitor(FieldVisitorAccurateEquals(), constant->value, zero))
496	                || (function->name == "notEquals"  /// indexOf(...) != c, c = 0
497	                    && applyVisitor(FieldVisitorAccurateEquals(), constant->value, zero))
498	                || (function->name == (reversed ? "less" : "greater")   /// indexOf(...) > c, c >= 0
499	                    && !applyVisitor(FieldVisitorAccurateLess(), constant->value, zero))
500	                || (function->name == (reversed ? "lessOrEquals" : "greaterOrEquals")   /// indexOf(...) >= c, c > 0
501	                    && applyVisitor(FieldVisitorAccurateLess(), zero, constant->value));
502	        }
503	    }
504	
505	    return false;
506	}
